      tl.from(t, { autoAlpha: 0, x: nar ? 0 : 14, y: nar ? 12 : 0, duration: 0.45, ease: 'power2.out', clearProps: 'transform,opacity,visibility' }, tOut + 0.4 + i * 0.2);
